CREATE TABLE public.role_t (
    role_id integer NOT NULL,
    role_code public."Role" NOT NULL,
    role_name text NOT NULL,
    i_ts timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    u_ts timestamp(3) without time zone,
    crte_usr_id text,
    updte_usr_id text,
    a_in smallint DEFAULT 1 NOT NULL,
    d_ts timestamp(3) without time zone,
    CONSTRAINT role_t_a_in_check CHECK ((a_in = ANY (ARRAY[0, 1])))
);

ALTER TABLE ONLY public.role_t
    ADD CONSTRAINT role_t_pkey PRIMARY KEY (role_id);

ALTER TABLE ONLY public.role_t
    ADD CONSTRAINT role_t_role_code_key UNIQUE (role_code);

ALTER TABLE ONLY public.role_t
    ADD CONSTRAINT role_t_role_id_role_code_key UNIQUE (role_id, role_code);

CREATE TRIGGER role_t_audit_timestamps BEFORE UPDATE ON public.role_t FOR EACH ROW EXECUTE FUNCTION public.campus_set_audit_timestamps();

